use super::codec::url_decode_bytes;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct URL {
    scheme: String,
    host: String,
    path: String,
    query: String,
}

impl URL {
    pub fn new(input: impl AsRef<str>) -> Self {
        let input = input.as_ref();
        let (scheme, remainder) = split_scheme(input);
        let (host, remainder) = split_host(remainder);
        let (path, query) = split_path_and_query(remainder);

        Self {
            scheme: scheme.to_owned(),
            host: host.to_owned(),
            path: path.to_owned(),
            query: query.to_owned(),
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn query_params(&self) -> Vec<(Vec<u8>, Vec<u8>)> {
        if self.query.is_empty() {
            return Vec::new();
        }

        self.query
            .split('&')
            .map(|pair| {
                let (key, value) = pair.split_once('=').unwrap_or((pair, ""));
                (
                    url_decode_bytes(key.as_bytes()),
                    url_decode_bytes(value.as_bytes()),
                )
            })
            .collect()
    }
}

fn split_scheme(input: &str) -> (&str, &str) {
    if let Some(index) = input.find("://") {
        (&input[..index], &input[index + 3..])
    } else {
        ("", input)
    }
}

fn split_host(input: &str) -> (&str, &str) {
    let host_end = input
        .char_indices()
        .find_map(|(index, ch)| matches!(ch, '/' | '?' | '#').then_some(index))
        .unwrap_or(input.len());

    (&input[..host_end], &input[host_end..])
}

fn split_path_and_query(input: &str) -> (&str, &str) {
    let without_fragment = input.split_once('#').map_or(input, |(head, _)| head);

    if let Some(index) = without_fragment.find('?') {
        (&without_fragment[..index], &without_fragment[index + 1..])
    } else {
        (without_fragment, "")
    }
}

