use super::codec::url_decode;

#[derive(Clone, Debug)]
pub struct URL {
    scheme: String,
    host: String,
    path: String,
    query: String,
    query_params: Vec<(Vec<u8>, Vec<u8>)>,
}

impl URL {
    pub fn new(input: String) -> Self {
        let (scheme, remainder) = split_scheme(&input);
        let (host, after_host) = split_host(remainder);
        let (path, query) = split_path_and_query(after_host);
        let query_params = parse_query_params(&query);

        Self {
            scheme,
            host,
            path,
            query,
            query_params,
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn query_params(&self) -> Vec<(Vec<u8>, Vec<u8>)> {
        self.query_params.clone()
    }
}

fn split_scheme(input: &str) -> (String, &str) {
    if let Some(position) = input.find("://") {
        (input[..position].to_string(), &input[position + 3..])
    } else {
        (String::new(), input)
    }
}

fn split_host(input: &str) -> (String, &str) {
    let end = input.find(['/', '?', '#']).unwrap_or(input.len());
    (input[..end].to_string(), &input[end..])
}

fn split_path_and_query(input: &str) -> (String, String) {
    let path_end = input.find(['?', '#']).unwrap_or(input.len());
    let path = input[..path_end].to_string();

    if let Some(query_start) = input[path_end..].strip_prefix('?') {
        let query_end = query_start.find('#').unwrap_or(query_start.len());
        (path, query_start[..query_end].to_string())
    } else {
        (path, String::new())
    }
}

fn parse_query_params(query: &str) -> Vec<(Vec<u8>, Vec<u8>)> {
    if query.is_empty() {
        return Vec::new();
    }

    query
        .split('&')
        .filter(|segment| !segment.is_empty())
        .map(|segment| {
            if let Some(position) = segment.find('=') {
                (
                    url_decode(segment[..position].as_bytes()),
                    url_decode(segment[position + 1..].as_bytes()),
                )
            } else {
                (url_decode(segment.as_bytes()), Vec::new())
            }
        })
        .collect()
}

