pub use self::codec::{url_decode, url_decode_bytes, url_encode};
pub use self::url::URL;

pub fn url_encode(input: &str) -> String {
    let mut encoded = String::with_capacity(input.len() * 3);

    for &byte in input.as_bytes() {
        if is_unreserved(byte) {
            encoded.push(byte as char);
        } else {
            encoded.push('%');
            encoded.push(to_lower_hex(byte >> 4));
            encoded.push(to_lower_hex(byte & 0x0f));
        }
    }

    encoded
}

pub fn url_decode(input: &str) -> Vec<u8> {
    url_decode_bytes(input.as_bytes())
}

pub fn url_decode_bytes(input: &[u8]) -> Vec<u8> {
    let mut decoded = Vec::with_capacity(input.len());
    let mut index = 0;

    while index < input.len() {
        match input[index] {
            b'+' => {
                decoded.push(b' ');
                index += 1;
            }
            b'%' if index + 2 < input.len() => {
                if let (Some(high), Some(low)) =
                    (from_hex(input[index + 1]), from_hex(input[index + 2]))
                {
                    decoded.push((high << 4) | low);
                    index += 3;
                } else {
                    decoded.push(b'%');
                    index += 1;
                }
            }
            byte => {
                decoded.push(byte);
                index += 1;
            }
        }
    }

    decoded
}

fn is_unreserved(byte: u8) -> bool {
    byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b'~')
}

fn to_lower_hex(nibble: u8) -> char {
    match nibble {
        0..=9 => (b'0' + nibble) as char,
        10..=15 => (b'a' + (nibble - 10)) as char,
        _ => unreachable!(),
    }
}

fn from_hex(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::{url_decode, url_decode_bytes, url_encode};

    #[test]
    fn encode_matches_observed_unreserved_set() {
        assert_eq!(url_encode("Hello World"), "Hello%20World");
        assert_eq!(url_encode("a+b%20c"), "a%2bb%2520c");
        assert_eq!(url_encode("~"), "~");
        assert_eq!(url_encode("!*'()"), "%21%2a%27%28%29");
        assert_eq!(url_encode("汉字"), "%e6%b1%89%e5%ad%97");
    }

    #[test]
    fn decode_matches_observed_rules() {
        assert_eq!(url_decode("a+b%20c"), b"a b c");
        assert_eq!(url_decode("%2F"), b"/");
        assert_eq!(url_decode("%2f"), b"/");
        assert_eq!(url_decode("%"), b"%");
        assert_eq!(url_decode("%2"), b"%2");
        assert_eq!(url_decode("%zz"), b"%zz");
        assert_eq!(url_decode("%2G"), b"%2G");
    }

    #[test]
    fn decode_preserves_raw_bytes() {
        assert_eq!(url_decode("%ff"), vec![0xff]);
        assert_eq!(url_decode("%00"), vec![0x00]);
        assert_eq!(url_decode_bytes(b"%80"), vec![0x80]);
    }
}

use std::env;
use std::io::{self, Write};
use std::process;

#[path = "src/url_parser/mod.rs"]
mod url_parser;

fn write_line<W: Write>(writer: &mut W, bytes: &[u8]) -> io::Result<()> {
    writer.write_all(bytes)?;
    writer.write_all(b"\n")
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        process::exit(1);
    }

    let input = &args[1];
    let encoded = url_parser::url_encode(input);
    let decoded = url_parser::url_decode(input);
    let parser = url_parser::URL::new(format!("http://example.com/test?q={encoded}"));

    let mut stdout = io::stdout().lock();

    writeln!(stdout, "{encoded}").expect("failed to write encoded output");
    write_line(&mut stdout, &decoded).expect("failed to write decoded output");
    writeln!(stdout, "{}", parser.scheme()).expect("failed to write scheme");
    writeln!(stdout, "{}", parser.host()).expect("failed to write host");
    writeln!(stdout, "{}", parser.path()).expect("failed to write path");
    writeln!(stdout, "{}", parser.query()).expect("failed to write query");

    for (key, value) in parser.query_params() {
        let decoded_key = url_parser::url_decode_bytes(&key);
        let decoded_value = url_parser::url_decode_bytes(&value);
        write_line(&mut stdout, &decoded_key).expect("failed to write query key");
        write_line(&mut stdout, &decoded_value).expect("failed to write query value");
    }
}
